css:
.fx-csw{width:min(760px,100%);display:grid;grid-template-columns:1.1fr 1fr;gap:2em;align-items:center}
.fx-csw .stage{position:relative;aspect-ratio:1/1;border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 92%,var(--text))}
.fx-csw .layer{position:absolute;inset:0;opacity:0;transition:opacity calc(.45s/var(--speed));display:grid;place-items:center}
.fx-csw .layer.on{opacity:1}
.fx-csw .shape{width:56%;aspect-ratio:1;border-radius:46% 46% 18% 18%;background:var(--c);box-shadow:inset -14px -18px 0 color-mix(in srgb,#000 12%,transparent)}
.fx-csw h3{font-size:1.7em}.fx-csw .nm{margin:.3em 0 1em;opacity:.7}
.fx-csw .sw{display:flex;gap:.7em;margin-bottom:1em}
.fx-csw .sw button{width:2.6em;height:2.6em;border-radius:50%;border:1px solid var(--border);background:var(--c);cursor:pointer;padding:0;outline-offset:3px;transition:transform calc(.2s/var(--speed))}
.fx-csw .sw button:hover{transform:scale(1.12)}
.fx-csw .sw button[aria-checked=true]{outline:2px solid var(--primary)}
.fx-csw .stock{font-size:.9em;color:var(--accent);font-weight:700;min-height:1.4em}
@media(max-width:640px){.fx-csw{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.fx-csw .layer,.fx-csw .sw button{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-csw .sw button.is-tap{transform:scale(1.12)}
